{
  "extractions": [
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "There are three types of procurement methods described in § 200.320: informal procurement methods (for micro-purchases and simplified acquisitions), formal procurement methods (through sealed bids or proposals), and noncompetitive procurement methods.",
        "kind": "statement",
        "modality": "not_stated",
        "references": ["§ 200.320"]
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "For any of the three procurement methods described in § 200.320, the recipient or subrecipient must maintain and use documented procurement procedures, consistent with the standards of § 200.320 and §§ 200.317, 200.318, and 200.319.",
        "kind": "requirement",
        "modality": "must",
        "references": ["§ 200.320", "§ 200.317", "§ 200.318", "§ 200.319"]
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "Informal procurement methods expedite the completion of transactions, minimize administrative burdens, and reduce costs.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "Informal procurement methods may be used when the value of the procurement transaction under the Federal award does not exceed the simplified acquisition threshold as defined in § 200.1.",
        "kind": "permission",
        "modality": "may",
        "references": ["§ 200.1"]
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "Recipients and subrecipients may establish a threshold lower than the simplified acquisition threshold defined in § 200.1 for informal procurement methods.",
        "kind": "permission",
        "modality": "may",
        "references": ["§ 200.1"]
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "For micro-purchases, the aggregate amount of the procurement transaction does not exceed the micro-purchase threshold defined in § 200.1.",
        "kind": "statement",
        "modality": "not_stated",
        "references": ["§ 200.1"]
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "To the extent practicable, the recipient or subrecipient should distribute micro-purchases equitably among qualified suppliers.",
        "kind": "recommendation",
        "modality": "should"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "Micro-purchases may be awarded without soliciting competitive price or rate quotations if the recipient or subrecipient considers the price reasonable based on research, experience, purchase history, or other information, and maintains documents to support its conclusion.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "Purchase cards may be used as a method of payment for micro-purchases.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "statement": "The recipient or subrecipient is responsible for determining and documenting an appropriate micro-purchase threshold based on internal controls, an evaluation of risk, and its documented procurement procedures.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "statement": "The micro-purchase threshold used by the recipient or subrecipient must be authorized or not prohibited under State, local, or tribal laws or regulations.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "statement": "The recipient or subrecipient may establish a micro-purchase threshold higher than the Federal threshold established in the Federal Acquisition Regulations (FAR) in accordance with paragraphs (a)(1)(iv) and (v) of § 200.320.",
        "kind": "permission",
        "modality": "may",
        "references": ["paragraphs (a)(1)(iv) and (v) of this section"]
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "statement": "The recipient or subrecipient may establish a threshold higher than the micro-purchase threshold identified in the FAR in accordance with the requirements of § 200.320.",
        "kind": "permission",
        "modality": "may",
        "references": ["§ 200.320"]
      }
    },
    {
      "unit": "F006:F009",
      "unit_attributes": {
        "statement": "The recipient or subrecipient may self-certify a micro-purchase threshold up to $50,000 on an annual basis, and must maintain documentation to be made available to the Federal agency or pass-through entity and auditors in accordance with § 200.334; the self-certification must include a justification, clear identification of the threshold, and supporting documentation of any of the following: (A) a qualification as a low-risk auditee in accordance with the criteria in § 200.520 for the most recent audit; (B) an annual internal institutional risk assessment to identify, mitigate, and manage financial risks; or (C) for public institutions, that a higher threshold is consistent with State law.",
        "kind": "permission",
        "modality": "may",
        "references": ["§ 200.334", "§ 200.520"]
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "statement": "Micro-purchase thresholds higher than $50,000 must be approved by the cognizant agency for indirect costs.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "statement": "When increasing the micro-purchase threshold over $50,000, the recipient or subrecipient must submit a request that includes the requirements in paragraph (a)(1)(iv) of § 200.320.",
        "kind": "requirement",
        "modality": "must",
        "references": ["paragraph (a)(1)(iv) of this section"]
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "statement": "An increased micro-purchase threshold over $50,000 is valid until any factor that was relied on in the establishment and rationale of the threshold changes.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "statement": "For simplified acquisitions, the aggregate dollar amount of the procurement transaction is higher than the micro-purchase threshold but does not exceed the simplified acquisition threshold.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "statement": "If simplified acquisition procedures are used, price or rate quotations must be obtained from an adequate number of qualified sources.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "statement": "When simplified acquisition procedures are used, the recipient or subrecipient may exercise judgment in determining what number of qualified sources is adequate, unless specified by the Federal agency.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F012",
      "unit_attributes": {
        "statement": "The recipient or subrecipient is responsible for determining an appropriate simplified acquisition threshold based on internal controls, an evaluation of risk, and its documented procurement procedures, which may be lower than, but must not exceed, the threshold established in the FAR.",
        "kind": "prohibition",
        "modality": "must_not"
      }
    },
    {
      "unit": "F013",
      "unit_attributes": {
        "statement": "Formal procurement methods are required when the value of the procurement transaction under a Federal award exceeds the simplified acquisition threshold of the recipient or subrecipient.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F013",
      "unit_attributes": {
        "statement": "Formal procurement methods are competitive and require public notice.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F014",
      "unit_attributes": {
        "statement": "Sealed bids is a procurement method in which bids are publicly solicited through an invitation and a firm fixed-price contract (lump sum or unit price) is awarded to the responsible bidder whose bid conforms with all the material terms and conditions of the invitation and is the lowest in price.",
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F014",
      "unit_attributes": {
        "statement": "The sealed bids procurement method is preferred for procuring construction services.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F015:F017",
      "unit_attributes": {
        "statement": "For sealed bidding to be feasible, the following conditions should be present: (A) a complete, adequate, and realistic specification or purchase description is available; (B) two or more responsible bidders have been identified as willing and able to compete effectively for the business; and (C) the procurement lends itself to a firm-fixed-price contract, and the selection of the successful bidder can be made principally based on price.",
        "kind": "recommendation",
        "modality": "should"
      }
    },
    {
      "unit": "F018:F019",
      "unit_attributes": {
        "statement": "If sealed bids are used, bids must be solicited from an adequate number of qualified sources, providing them with sufficient response time prior to the date set for opening the bids.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F018:F019",
      "unit_attributes": {
        "statement": "If sealed bids are used, the recipient or subrecipient may exercise judgment in determining what number of qualified sources is adequate, unless specified by the Federal agency.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F018:F019",
      "unit_attributes": {
        "statement": "If sealed bids are used, the invitation for bids must be publicly advertised for local governments.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F018:F020",
      "unit_attributes": {
        "statement": "If sealed bids are used, the invitation for bids must define the items or services with specific information, including any required specifications, for the bidder to properly respond.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F018:F021",
      "unit_attributes": {
        "statement": "If sealed bids are used, all bids will be opened at the time and place prescribed in the invitation for bids, and for local governments, the bids must be opened publicly.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F018:F022",
      "unit_attributes": {
        "statement": "If sealed bids are used, a firm-fixed-price contract is awarded in writing to the lowest responsive bid and responsible bidder.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F018:F022",
      "unit_attributes": {
        "statement": "If sealed bids are used, when specified in the invitation for bids, factors such as discounts, transportation cost, and life-cycle costs must be considered in determining which bid is the lowest.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F018:F022",
      "unit_attributes": {
        "statement": "If sealed bids are used, payment discounts must only be used to determine the low bid when the recipient or subrecipient determines they are a valid factor based on prior experience.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F018:F023",
      "unit_attributes": {
        "statement": "If sealed bids are used, the recipient or subrecipient must document and provide a justification for all bids it rejects.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F024",
      "unit_attributes": {
        "statement": "Proposals is a procurement method used when conditions are not appropriate for using sealed bids.",
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F024",
      "unit_attributes": {
        "statement": "The proposals procurement method may result in either a fixed-price or cost-reimbursement contract.",
        "kind": "statement",
        "modality": "possible"
      }
    },
    {
      "unit": "F024:F025",
      "unit_attributes": {
        "statement": "When the proposals procurement method is used, requests for proposals require public notice, and all evaluation factors and their relative importance must be identified.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F024:F025",
      "unit_attributes": {
        "statement": "When the proposals procurement method is used, proposals must be solicited from multiple qualified entities.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F024:F025",
      "unit_attributes": {
        "statement": "When the proposals procurement method is used, any proposals submitted in response to the public notice must be considered to the maximum extent practicable.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F024:F026",
      "unit_attributes": {
        "statement": "When the proposals procurement method is used, the recipient or subrecipient must have written procedures for conducting technical evaluations and making selections.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F024:F027",
      "unit_attributes": {
        "statement": "When the proposals procurement method is used, contracts must be awarded to the responsible offeror whose proposal is most advantageous to the recipient or subrecipient considering price and other factors.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F024:F028",
      "unit_attributes": {
        "statement": "When using proposals, the recipient or subrecipient may use competitive proposal procedures for qualifications-based procurement of architectural/engineering (A/E) professional services whereby the offeror's qualifications are evaluated, and the most qualified offeror is selected, subject to negotiation of fair and reasonable compensation.",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F024:F028",
      "unit_attributes": {
        "statement": "The qualifications-based competitive proposal method where price is not used as a selection factor can only be used to procure architectural/engineering (A/E) professional services.",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F024:F028",
      "unit_attributes": {
        "statement": "The qualifications-based competitive proposal method where price is not used as a selection factor may not be used to purchase other services provided by A/E firms that are a potential source to perform the proposed effort.",
        "kind": "prohibition",
        "modality": "must_not"
      }
    },
    {
      "unit": "F029:F034",
      "unit_attributes": {
        "statement": "The recipient or subrecipient may use a noncompetitive procurement method only if one of the following circumstances applies: (1) the aggregate amount of the procurement transaction does not exceed the micro-purchase threshold (see paragraph (a)(1) of § 200.320); (2) the procurement transaction can only be fulfilled by a single source; (3) the public exigency or emergency for the requirement will not permit a delay resulting from providing public notice of a competitive solicitation; (4) the recipient or subrecipient requests in writing to use a noncompetitive procurement method, and the Federal agency or pass-through entity provides written approval; or (5) after soliciting several sources, competition is determined inadequate.",
        "kind": "permission",
        "modality": "may",
        "references": ["paragraph (a)(1) of this section"]
      }
    }
  ]
}
